project:
  type: website
  output-dir: _site

website:
  title: "Your Name"
  navbar:
    background: "#F5F5F0"
    left:
      - text: "Home"
        href: "index.qmd"
      - text: "Projects"
        href: "projects.qmd"
      - text: "Blog"
        href: "blog.qmd"

format:
  html:
    theme: cosmo
    css: styles/styles.css
    toc: false
    link-external-newwindow: true



Create styles/styles.css for the minimalist design:
/* Hero section split layout */
.hero {
  display: grid;
  grid-template-columns: 60% 40%;
  min-height: 100vh;
  gap: 2rem;
}

/* Typography */
h1 {
  font-size: 4rem;
  font-weight: 300;
  line-height: 1.2;
}

/* Colors */
:root {
  --background: #F5F5F0;
  --text: #2C2C2C;
  --accent: #2C2C2C;
}

body {
  background-color: var(--background);
  color: var(--text);
}
